import React from 'react';
import { Navbar, Nav, Container, NavDropdown } from 'react-bootstrap';
import Link from 'next/link';
import { useTheme } from '../context/ThemeContext';

import logo from '../assets/logo.png';

const AppNavbar = () => {
  const { theme, toggleTheme } = useTheme();

  return (
    <Navbar expand="lg" fixed="top" className="navbar-custom">
      <Container>
        <Link href="/" passHref legacyBehavior>
            <Navbar.Brand className="d-flex align-items-center gap-2">
                <img 
                    src={logo.src} 
                    alt="Business tools" 
                    style={{ height: '30px', width: 'auto' }} 
                    className="d-inline-block align-top" 
                />
                <span className="font-bold text-lg">Business Tools</span>
            </Navbar.Brand>
        </Link>
        
        <div className="d-flex align-items-center gap-3 order-lg-last ms-lg-3">
             <div className="theme-toggle" onClick={toggleTheme} style={{ cursor: 'pointer', fontSize: '1.2rem', padding: '0.5rem' }}>
                <i className={`fas ${theme === 'dark' ? 'fa-sun' : 'fa-moon'}`}></i>
            </div>
            <Navbar.Toggle aria-controls="basic-navbar-nav" />
        </div>

        <Navbar.Collapse id="basic-navbar-nav">
          <Nav className="ms-auto align-items-center">
             <NavDropdown title="Menu" id="basic-nav-dropdown" align="end">
                <Link href="/" passHref legacyBehavior><NavDropdown.Item>Início</NavDropdown.Item></Link>
                <Link href="/text-editor" passHref legacyBehavior><NavDropdown.Item>Editor de Texto</NavDropdown.Item></Link>
                <Link href="/pdf-tools" passHref legacyBehavior><NavDropdown.Item>PDF Tools</NavDropdown.Item></Link>
                <Link href="/bpmn" passHref legacyBehavior><NavDropdown.Item>Fluxograma BPMN</NavDropdown.Item></Link>
             </NavDropdown>
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
};

export default AppNavbar;
